BEGIN;

-- Ficha de Ramón Torres.
--
-- La biografía de relleno no daba un solo dato de su obra. aliases: + El Poeta (Acento 2026,
-- Diario Libre 2022). Sin premios: la columna de Acento (2026) pide El Gran Soberano, no lo
-- registra. Año de llegada a Santo Domingo en conflicto (1977/1987): se da como finales de
-- los ochenta según la mayoría de las fuentes.

UPDATE artists SET aliases = ARRAY['El Poeta de la Bachata', 'El Poeta', 'Francisco Pache Torres']::text[] WHERE slug = 'ramon-torres';

